import asyncio
import re

async def act(page):
    # Extract unique repository names from the main section
    main = page.get_by_role('main')
    links = await main.get_by_role('link').all()
    repo_links = []
    for link in links:
        name = await link.text_content()
        href = await link.get_attribute('href')
        if name and href and '/' in name and 'avatar' not in name.lower() and href.startswith('/') and '/' in href[1:]:
            # This likely is a repository link
            repo_links.append((name.strip(), href))
    # Deduplicate by href to avoid multiple entries for the same repo
    unique_repos = {}
    for name, href in repo_links:
        if href not in unique_repos:
            unique_repos[href] = name

    qualifying_repos = []

    for href, repo_name in unique_repos.items():
        try:
            # Click the repository link using a precise selector
            link = main.get_by_role('link', name=repo_name, exact=True).first
            await link.click()
            await asyncio.sleep(3)  # Wait for page load

            # Find star count on repository page
            star_count = None
            # Look for buttons that might contain star count
            buttons = await page.get_by_role('button').all()
            for button in buttons:
                text = await button.text_content()
                if text and text.strip().isdigit():
                    star_count = int(text.strip())
                    break
            if star_count is None:
                # Look for status or other roles
                status_elements = await page.get_by_role('status').all()
                for elem in status_elements:
                    text = await elem.text_content()
                    if text and 'star' in text.lower():
                        numbers = re.findall(r'\d+', text.replace(',', ''))
                        if numbers:
                            star_count = int(numbers[0])
                            break
            if star_count is None:
                # Try generic text elements if necessary
                all_text = await page.get_by_role('text').all()
                for elem in all_text:
                    text = await elem.text_content()
                    if text and 'star' in text.lower():
                        numbers = re.findall(r'\d+', text.replace(',', ''))
                        if numbers:
                            star_count = int(numbers[0])
                            break

            if star_count and star_count > 100:
                qualifying_repos.append(repo_name)

            # Navigate back to activity page
            await page.go_back()
            await asyncio.sleep(2)
        except Exception as e:
            print(f"Error processing {repo_name}: {e}")
            continue

    # Return result
    if qualifying_repos:
        return ', '.join(qualifying_repos)
    else:
        return "No repositories found with more than 100 stars."

